.topbar{
  position:fixed;top:0;left:0;right:0;z-index:20;display:flex;justify-content:space-between;align-items:center;
  padding:1.05rem clamp(1rem,3vw,2rem);font-size:.7rem;letter-spacing:.28em;text-transform:uppercase;
}
.brand{font-family:'Cinzel',serif;color:var(--cream);text-decoration:none;font-weight:700;letter-spacing:.34em;display:flex;align-items:center;gap:.7em}
.brand i{width:9px;height:9px;background:var(--gold);transform:rotate(45deg);display:inline-block;box-shadow:0 0 14px rgba(217,168,63,.9);transition:transform .5s}
